use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum RetrievalBackend {
    SnapshotDense,
    QdrantHybrid,
}

#[derive(Debug)]
pub struct SearchError(pub String);

impl fmt::Display for SearchError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "SearchError: {}", self.0)
    }
}

/// Search for skills using the configured backend.
/// Every backend arm must either implement its own real path or fail loud;
/// silent delegation to another arm mislabels results.
pub fn search(
    backend: &RetrievalBackend,
    query: &str,
) -> Result<Vec<String>, SearchError> {
    let dense_results = vec![format!("dense:{}", query)];
    match backend {
        RetrievalBackend::SnapshotDense => Ok(dense_results),
        // BUG: silently clones dense results — callers believe they got hybrid results
        RetrievalBackend::QdrantHybrid => Ok(dense_results.clone()),
    }
}
